NS_IMETHODIMP
nsCharsetConverterManager::GetCharsetAlias(const char* charset,
                                           nsACString& result) {
  NS_ENSURE_ARG_POINTER(charset);
  nsAutoCString label(charset);
  if (label.IsEmpty()) return NS_ERROR_NULL_POINTER;
  ToLowerCase(label);

  const mozilla::Encoding* encoding = mozilla::Encoding::ForLabel(label);
  if (encoding) {
    if (encoding == REPLACEMENT_ENCODING) {
      return NS_ERROR_UCONV_NOCONV;
    }
    encoding->Name(result);
    return NS_OK;
  }

  for (const auto& alias : kAliases) {
    if (label.Equals(alias.label)) {
      result = alias.name;
      return NS_OK;
    }
  }

  result.Truncate();
  return NS_ERROR_NOT_AVAILABLE;
}

